package connect

import "errors"

// ResultOf returns the winner of a game of Hex given the board as a slice
// of lines. Player "O" plays from top to bottom, player "X" plays from
// left to right. An empty string is returned if no player has won.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}

	board := make([][]rune, len(lines))
	for i, line := range lines {
		board[i] = []rune(line)
		for _, c := range board[i] {
			if c != '.' && c != 'O' && c != 'X' {
				return "", errors.New("invalid board: expected only '.', 'O' or 'X'")
			}
		}
	}

	if connects(board, 'O') {
		return "O", nil
	}
	if connects(board, 'X') {
		return "X", nil
	}
	return "", nil
}

// connects reports whether the given player has a path of stones from one
// of their edges to the opposite edge.
//
// The board is a slanted parallelogram: each row is shifted one cell to
// the right relative to the row above it. A cell at (r, c) is therefore
// adjacent to (r, c-1), (r, c+1), (r-1, c), (r-1, c+1), (r+1, c-1) and
// (r+1, c).
//
// Player "O" wins by connecting the top row to the bottom row, player "X"
// wins by connecting the left column to the right column.
func connects(board [][]rune, player rune) bool {
	rows := len(board)

	startEdge := func(r, c int) bool {
		if player == 'O' {
			return r == 0 // top
		}
		return c == 0 // left
	}
	endEdge := func(r, c int) bool {
		if player == 'O' {
			return r == rows-1 // bottom
		}
		return c == len(board[r])-1 // right
	}

	visited := make([][]bool, rows)
	queue := [][2]int{}
	for r := 0; r < rows; r++ {
		visited[r] = make([]bool, len(board[r]))
		for c := 0; c < len(board[r]); c++ {
			if board[r][c] == player && startEdge(r, c) {
				visited[r][c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
	}

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		r, c := cur[0], cur[1]

		if endEdge(r, c) {
			return true
		}

		for _, n := range [][2]int{
			{r, c - 1}, {r, c + 1},
			{r - 1, c}, {r - 1, c + 1},
			{r + 1, c - 1}, {r + 1, c},
		} {
			nr, nc := n[0], n[1]
			if nr < 0 || nr >= rows || nc < 0 || nc >= len(board[nr]) {
				continue
			}
			if board[nr][nc] == player && !visited[nr][nc] {
				visited[nr][nc] = true
				queue = append(queue, [2]int{nr, nc})
			}
		}
	}
	return false
}
